@page{margin:36px 42px 48px}body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#23302b;line-height:1.5}h1{font-size:22px;color:#14352a;font-weight:normal;margin:12px 0}h2{font-size:14px;color:#14352a;background:#f2f4f0;padding:9px 12px;margin:20px 0 12px;page-break-after:avoid}h3{font-size:11px;color:#14352a;margin:16px 0 6px;page-break-after:avoid}h4{font-size:10px;page-break-after:avoid}p{white-space:pre-wrap;overflow-wrap:break-word;margin:6px 0 10px}.header img{max-height:52px;max-width:165px}.document-code,.code{font-size:8px;color:#657269}.footer{position:fixed;bottom:-27px;font-size:8px;color:#657269}.page:after{content:counter(page)}.report-part{page-break-before:always}.report-note{padding:10px 12px;background:#f5f2ec}.label{font-weight:bold}.answer{margin-bottom:12px}.missing{color:#80551d}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:7px;text-align:left;vertical-align:top;word-wrap:break-word;border:1px solid #dcdfd9}th{background:#edf1ec;font-size:9px}thead{display:table-header-group}.approval{padding:8px 0}
